window.ScripturaLexicons.BDAG_PART_0233 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0233-01\" data-source=\"BDAG\" data-search=\"μετανοέω verbo mudar de ideia; arrepender-se; converter-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μετανοέω</td><td>verbo</td><td>mudar de ideia; arrepender-se; converter-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0233-02\" data-source=\"BDAG\" data-search=\"μετάνοια, ας, ἡ substantivo feminino arrependimento; conversão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μετάνοια, ας, ἡ</td><td>substantivo feminino</td><td>arrependimento; conversão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0233-03\" data-source=\"BDAG\" data-search=\"μεταξύ advérbio e preposição entre; no meio; depois; entre si BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεταξύ</td><td>advérbio e preposição</td><td>entre; no meio; depois; entre si</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0233-04\" data-source=\"BDAG\" data-search=\"μεταπαραδίδωμι verbo suceder; dar lugar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεταπαραδίδωμι</td><td>verbo</td><td>suceder; dar lugar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0233-05\" data-source=\"BDAG\" data-search=\"μεταπέμπω verbo mandar chamar; convocar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεταπέμπω</td><td>verbo</td><td>mandar chamar; convocar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0233-06\" data-source=\"BDAG\" data-search=\"μεταστρέφω verbo mudar; alterar; deturpar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεταστρέφω</td><td>verbo</td><td>mudar; alterar; deturpar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0233-07\" data-source=\"BDAG\" data-search=\"μετασχηματίζω verbo transformar; disfarçar; aplicar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μετασχηματίζω</td><td>verbo</td><td>transformar; disfarçar; aplicar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0233-08\" data-source=\"BDAG\" data-search=\"μετατίθημι verbo transferir; mudar; abandonar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μετατίθημι</td><td>verbo</td><td>transferir; mudar; abandonar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0233-09\" data-source=\"BDAG\" data-search=\"μετατρέπω verbo virar; ser transformado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μετατρέπω</td><td>verbo</td><td>virar; ser transformado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0233-10\" data-source=\"BDAG\" data-search=\"μεταυτίκα advérbio logo depois BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεταυτίκα</td><td>advérbio</td><td>logo depois</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0233-11\" data-source=\"BDAG\" data-search=\"μεταφέρω verbo transportar; levar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεταφέρω</td><td>verbo</td><td>transportar; levar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0233-12\" data-source=\"BDAG\" data-search=\"μεταφυτεύω verbo transplantar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μεταφυτεύω</td><td>verbo</td><td>transplantar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0233-13\" data-source=\"BDAG\" data-search=\"μετέβη forma verbal remissiva ver μεταβαίνω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μετέβη</td><td>forma verbal remissiva</td><td>ver μεταβαίνω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0233-14\" data-source=\"BDAG\" data-search=\"μετενδύω verbo mudar de roupa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μετενδύω</td><td>verbo</td><td>mudar de roupa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0233-15\" data-source=\"BDAG\" data-search=\"μετέπειτα advérbio posteriormente; depois BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μετέπειτα</td><td>advérbio</td><td>posteriormente; depois</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0233-16\" data-source=\"BDAG\" data-search=\"μετέχω verbo participar; compartilhar; comer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μετέχω</td><td>verbo</td><td>participar; compartilhar; comer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0233-17\" data-source=\"BDAG\" data-search=\"μετεωρίζομαι verbo depoente estar ansioso; estar inquieto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μετεωρίζομαι</td><td>verbo depoente</td><td>estar ansioso; estar inquieto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0233-18\" data-source=\"BDAG\" data-search=\"μετῆρα forma verbal remissiva ver μεταίρω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μετῆρα</td><td>forma verbal remissiva</td><td>ver μεταίρω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0233-19\" data-source=\"BDAG\" data-search=\"μετοικεσία, ας, ἡ substantivo feminino deportação; cativeiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μετοικεσία, ας, ἡ</td><td>substantivo feminino</td><td>deportação; cativeiro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0233-20\" data-source=\"BDAG\" data-search=\"μετοικίζω verbo reassentar; deportar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">μετοικίζω</td><td>verbo</td><td>reassentar; deportar</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0233-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετανοέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μετανοέω</span>, futuro <span class=\"greek\">μετανοήσω</span>; 1º aoristo <span class=\"greek\">μετενόησα</span> (<span class=\"greek\">ἐμετενόησαν</span> com duplo aumento em ApcEsdr 2:24) (ver a entrada seguinte; Antiphon+).</p><p class=\"entry-text\">① Mudar de ideia, mudar de opinião Hv 3, 7, 3; m 11:4 (cf. Diod S 15, 47, 3 <span class=\"greek\">μετενόησεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">δῆμος</span>; 17, 5, 1; Epict. 2, 22, 35; Appian, Hann. 35 §151, Mithrid. 58 §238; Stob., Ecl. II 113, 5ff W.; PSI 495, 9 [258 a.C.]; Jos., Vi. 110; 262); daí,</p><p class=\"entry-text\">② Sentir remorso, arrepender-se, converter-se (em diversas relações e no âmbito de diferentes responsabilidades, morais, políticas, sociais ou religiosas: X., Hell. 1, 7, 19 <span class=\"greek\">οὐ</span> <span class=\"greek\">μετανοήσαντες</span> <span class=\"greek\">ὕστερον</span> <span class=\"greek\">εὑρήσετε</span> <span class=\"greek\">σφᾶς</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ἡμαρτηκότας</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μέγιστα</span> <span class=\"greek\">ἐς</span> <span class=\"greek\">θεούς</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">αὐτούς</span> = em vez de reconhecer tarde demais que cometestes gravíssimos pecados contra os deuses; Plut., Vi. Camill. 143 [29, 3], Galba 1055 [6, 4], também Mor. 74c; M. Ant. 8, 2 e 53; Ps.-Lucian, De Salt. 84 <span class=\"greek\">μετανοῆσαι</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">οἷς</span> <span class=\"greek\">ἐποίησεν</span>; Herm. Wr. 1, 28; OGI 751, 9 [II a.C.] <span class=\"greek\">θεωρῶν</span> <span class=\"greek\">οὖν</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">μετανενοηκότας</span> <span class=\"greek\">τε</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">προημαρτημένοις</span>; SIG 1268, 2, 8 [III a.C.] <span class=\"greek\">ἁμαρτὼν</span> <span class=\"greek\">μετανόει</span>; PSI 495, 9 [258/257 a.C.]; BGU 747 I, 11; 1024 IV, 25; PTebt 424, 5; Is 46:8; Jer 8:6; Sir 17:24; 48:15; frequentemente em Test12 Patr [ver índice]; Philo [ver <span class=\"greek\">μετάνοια</span>]; Jos., Bell. 5, 415, Ant. 7, 153; 320; Just.), em sentido ético-(religioso): <span class=\"greek\">ἐν</span> <span class=\"greek\">σάκκῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σποδῷ</span> <span class=\"greek\">μ</span>., arrepender-se em saco e cinza <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:13</a>. Como condição prévia para experimentar o Reino de Deus na pregação de João Batista e Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:2</a>; 4:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:15</a>. Como assunto da proclamação dos discípulos 6:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:30</a>; 26:20. A ausência de arrependimento conduz à destruição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:3</a>, 5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:20</a> (<span class=\"greek\">ἢ</span> … <span class=\"greek\">μετανοήσωσιν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ἐπιμείναντες</span> <span class=\"greek\">δικαίως</span> <span class=\"greek\">κριθῶσι</span> Hippol., Ref. 1, pref. 2). O arrependimento salva (cf. Philo, Spec. Leg. 1, 239 <span class=\"greek\">ὁ</span> <span class=\"greek\">μετανοῶν</span> <span class=\"greek\">σῴζεται</span>; 253; Just., D. 141, 2 <span class=\"greek\">ἐὰν</span> <span class=\"greek\">μετανοήσωσι</span>, <span class=\"greek\">πάντες</span> … <span class=\"greek\">τυχεῖν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐλέους</span> <span class=\"greek\">δύνανται</span>) 12:41; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:32</a>; cf. 15:7, 10; 16:30. <span class=\"greek\">μ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κήρυγμά</span> <span class=\"greek\">τινος</span>, arrepender-se diante da proclamação de alguém ou por causa dela <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:32</a> (B-D-F §207, 1; Rob. 593; ver <span class=\"greek\">εἰς</span> 10a). Com <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>, para indicar o motivo: arrepender-se de alguma coisa, por causa de algo (Chariton 3, 3, 11; Ps.-Lucian, Salt. 84; M. Ant. 8, 2; 10; 53; Jo 2:13; Jon 3:10; 4:2; Am 7:3, 6; Prayer of Manasseh [=Odes 12] 7; TestJud 15:4; Philo, Virt. 180; Jos., Ant. 7, 264; Just., D. 95, 3.—B-D-F §235, 2) <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀκαθαρσίᾳ</span>, da sua imoralidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:21</a>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἁμαρτήμασιν</span>, dos seus pecados 1 Cl 7:7 (Just., D. 141, 2; cf. OGI 751, 9f). <span class=\"greek\">ἐπί</span> seguido de infinitivo substantivado MPol 7:3 (Just., D. 123, 6). Também <span class=\"greek\">διά</span> <span class=\"greek\">τι</span> Hv 3, 7, 2. Uma vez que em <span class=\"greek\">μ</span>. predomina o impulso negativo de afastar-se, emprega-se também com <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>: arrepender-se e afastar-se de algo: <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κακίας</span> (Jer 8:6; Just., D. 109, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:22</a> (MWilcox, The Semitisms of Ac, ’65, 102–105). <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀνομίας</span> 1 Cl 8:3 (citação de origem desconhecida). Também <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:21b</a>, 22; 9:20f; 16:11. Com <span class=\"greek\">ἐπιστρέφειν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:20</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">ἑνότητα</span> <span class=\"greek\">θεοῦ</span>, voltar-se pelo arrependimento à unidade de Deus (que exclui toda desunião) IPhld 8:1b; cf. ISm 9:1. Mas <span class=\"greek\">μ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πάθος</span>, arrepender-se da maneira como pensam acerca do sofrimento (de Cristo, negado pelos docetistas) 5:3. Seguido de infinitivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:9</a>. Seguido de <span class=\"greek\">ὅτι</span>, arrepender-se porque ou de que (Jos., Ant. 2, 315) Hm 10, 2, 3. Com advérbio: <span class=\"greek\">ἀδιστάκτως</span> Hs 8, 10, 3. <span class=\"greek\">βραδύτερον</span> Hs 8, 7, 3; 8, 8, 3b. <span class=\"greek\">πυκνῶς</span> m 11:4. <span class=\"greek\">ταχύ</span> Hs 8, 7, 5; 8, 8, 3a; 5b; 8, 10, 1; 9, 19, 2; 9, 21, 4; 9, 23, 2c. <span class=\"greek\">μ</span>. <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὅλης</span> (<span class=\"greek\">τῆς</span>) <span class=\"greek\">καρδίας</span>, arrepender-se de todo o coração 2 Cl 8:2; 17:1; 19:1; Hv 1, 3, 2; 2, 2, 4; 3, 13, 4b; 4, 2, 5; m 5, 1, 7; 12, 6, 1; Hs 7:4; 8, 11, 3. <span class=\"greek\">μ</span>. <span class=\"greek\">ἐξ</span> <span class=\"greek\">εἰλικρινοῦς</span> <span class=\"greek\">καρδίας</span>, arrepender-se de coração sincero 2 Cl 9:8.—O vocábulo também se encontra, empregado absolutamente (Diod S 13, 53, 3; Epict., En 34; Oenomaus [época de Adriano] em Eus., PE 5, 19, 1 <span class=\"greek\">μετανοεῖτε</span> como exortação; Philo, Mos. 2, 167 e outros; Jos., Ant. 2, 322; Just., D. 12, 2; Theoph. Ant. 3, 24 [p. 254, 17]; <span class=\"greek\">εἰ</span> <span class=\"greek\">ἤκουσαν</span> <span class=\"greek\">μετανοήσαντες</span>, <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐπήγετο</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κατακλυσμός</span> Did., Gen. 186, 9; <span class=\"greek\">ἁμαρτωλὸς</span> … <span class=\"greek\">πρὸς</span> <span class=\"greek\">το͂</span> <span class=\"greek\">μετανοεῖν</span> <span class=\"greek\">πορευόμενος</span> Orig., C. Cels 3, 64, 5) Lk 17:3f; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:38</a>; 3:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:5a</a> (Vi. Aesopi G 85 P. <span class=\"greek\">μετανόησον</span> = pondera contigo mesmo), versículos 5b, 16, 21; 3:3, 19; 2 Cl 8:1, 2, 3; 13:1; 15:1; 16:1; IPhld 3:2; 8:1a; ISm 4:1; Hv 1, 1, 9; 3, 3, 2; 3, 5, 5; 3, 7, 6; 3, 13, 4a; 5:7; m 4, 1, 5; 7ff; 4, 2, 2; 4, 3, 6; 9:6; 10, 2, 4; 12, 3, 3; Hs 4:4; 6, 1, 3f; 6, 3, 6; 6, 5, 7; 7:2; 4f; 8, 6, 1ff; 8, 7, 2f; 8, 8, 2; 5a; 8, 9, 2; 4; 8, 11, 1f; 9, 14, 1f; 9, 20, 4; 9, 22, 3f; 9, 23, 2; 5; 9, 26, 6; 8; D 10:6; 15:3; PtK 3 p. 15, 11; 27.—Ver também MPol 9:2; 11:1f, no sentido de lamentar ter-se tornado cristão; AcPl Ha 1, 17.—Windisch, excursus sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:10</a> p. 233f; Norden, Agn. Th. 134ff; FShipham, ET 46, ’35, 277–80; EDietrich, D. Umkehr (Bekehrg. u. Busse) im AT u. im Judent. b. bes. Berücksichtigg. der ntl. Zeit ’36; HPohlmann, D. Metanoia ’38; OMichel, EvTh 5, ’38, 403–14; BPoschmann, Paenitentia secunda ’40, 1–205 (NT e Padres Apostólicos).—Sobre o caráter distintivo do uso neotestamentário, ver Thompson 28f, s.v. <span class=\"greek\">μεταμέλομαι</span>, final.—B. 1123. DELG s.v. <span class=\"greek\">νόος</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0233-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετάνοια, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μετάνοια</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">μετανοέω</span>), primariamente “mudança de opinião” (Thu. 3, 36, 4; Polyb. 4, 66, 7; Appian, Mithrid. 16 §57; papiros [ver New Docs 4, 160; Spicq II 475, 17]; TestSol 12:3 C; JosAs, ApcSed; ApcMos 32; Jos., C. Ap. 1, 274, Ant. 16, 125; Just., Tat.), também com o matiz de “remorso” (como pesar pelas faltas e erros: Batr. 69; Lycon, o peripatético [III a.C.], Fgm. 23 Wehrli [em Diog. L. 5, 66]; Polyb. 18, 33, 7; Stoic. III 147, linha 21f; Cebes 10, 4; 11, 1; Plut., Mor. 56a; 68f; 961d, Alex. 11, 4, Mar. 10, 4; 39, 3; Chariton 1, 3, 7; Appian, Liby. 52 §225; 102 §482; 116 §553; M. Ant. 8, 10; Ps.-Lucian, Calumn. 5; Jos., Ant. 13, 314. Sobre o “remorso” de Sofia: Iren. 1, 3, 1 [Harv. I 24, 7]); em nossa literatura, com ênfase na necessidade de mudança diante da responsabilidade para com a divindade (cf. Hierocles 14, 451; Sir 44:16; Wsd 12:10, 19; Prayer of Manasseh [=Odes 12] 8; Philo, Det. Pot. Ins. 96, Spec. Leg. 1, 58, Virt. 175ff [<span class=\"greek\">περὶ</span> <span class=\"greek\">μετανοίας</span>] e outros; EpArist 188; Jos., Ant. 9, 176; TestReub 2:1; TestJud 19:2; TestGad 5:7f; JosAs 15:6ff; 16:7; ApcSed prólogo: <span class=\"greek\">περὶ</span> <span class=\"greek\">ἀγάπης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">μ</span>.; 14:3 <span class=\"greek\">ἐν</span> <span class=\"greek\">μετανοίαις</span>; SibOr 1, 129; 168; Iren. 1, 21, 2 [Harv. 182, 7]; Orig., C. Cels. 7, 57, 3f; Did., Gen. 97, 15), arrependimento, mudança de rumo, conversão; como afastamento: <span class=\"greek\">μετάνοια</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">νεκρῶν</span> <span class=\"greek\">ἔργων</span>, abandono de obras mortas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:1</a>. Predominantemente quanto ao lado positivo do arrependimento, como começo de uma nova relação com Deus: <span class=\"greek\">ἡ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">θεὸυ</span> <span class=\"greek\">μ</span>., arrependimento que conduz a Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:21</a>. <span class=\"greek\">ἄξια</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μετανοίας</span> <span class=\"greek\">ἔργα</span>, obras condizentes com o arrependimento 26:20. Também <span class=\"greek\">καρπὸν</span> <span class=\"greek\">ἄξιον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:8</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:8</a>. <span class=\"greek\">βαπτίζειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>., batizar para arrependimento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:11</a> (ver <span class=\"greek\">βαπτίζω</span> 2a; também <span class=\"greek\">εἰς</span> 10a). <span class=\"greek\">βάπτισμα</span> <span class=\"greek\">μετανοίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:3</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:24</a>; 19:4 (alternativamente <span class=\"greek\">λουτροῦ</span> … <span class=\"greek\">τῆς</span> <span class=\"greek\">μ</span>. Just., D. 14, 1). <span class=\"greek\">χρείαν</span> <span class=\"greek\">ἔχειν</span> <span class=\"greek\">μετανοίας</span>, necessitar de arrependimento ou conversão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:7</a>. <span class=\"greek\">κηρύσσειν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">ἄφεσιν</span> <span class=\"greek\">ἁμαρτιῶν</span>, pregar arrependimento que conduz ao perdão dos pecados 24:47 (<span class=\"greek\">μετάνοιαν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἄφεσιν</span> <span class=\"greek\">ἁμαρτιῶν</span> <span class=\"greek\">διὰ</span> … <span class=\"greek\">λουτροῦ</span> <span class=\"greek\">παλλιγγενεσίας</span> Theoph. Ant. 2, 16 [p. 140. 8f]); cf. 1 Cl 7:6. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">καιρὸν</span> <span class=\"greek\">μετανοίας</span>, ainda ter tempo para arrependimento 2 Cl 8:2. <span class=\"greek\">τόπον</span> <span class=\"greek\">μετανοίας</span> <span class=\"greek\">διδόναι</span>, dar oportunidade de arrependimento (Wsd 12:10; cf. <span class=\"greek\">ἵνα</span> <span class=\"greek\">μετάνοια</span> <span class=\"greek\">δοθῇ</span> Did., Gen. 169, 4; <span class=\"greek\">ἀφορμὴν</span> <span class=\"greek\">μετανοίας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐξομολογήσεως</span> <span class=\"greek\">παράσχειν</span> Theoph. Ant. 2, 29 [p. 170, 17]) 1 Cl 7:5. <span class=\"greek\">μετανοίας</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">εὑρίσκειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:17</a> (cf. <span class=\"greek\">μετανοίας</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">ἔχειν</span> Tat. 15:3). <span class=\"greek\">διδόναι</span> <span class=\"greek\">τινὶ</span> (<span class=\"greek\">τὴν</span>) <span class=\"greek\">μ</span>. (cf. Wsd 12:19; M. J. Brutus, Ep. 7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:31</a>; 11:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:25</a>; 16:9; cf. Hv 4, 1, 3; Hs 8, 6, 2; 8, 11, 1. <span class=\"greek\">τιθέναι</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">μετάνοιαν</span>, prescrever arrependimento a alguém Hm 4, 3, 4; cf. 5; <span class=\"greek\">καλεῖν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:32</a> (ApcSed 15:2; Just., A I, 15, 7; 90, 7); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:13</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:17</a>, variante de leitura (cf. <span class=\"greek\">καλοῦνται</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">διόρθωσιν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span> <span class=\"greek\">αὐτῶν</span> Orig., C. Cels. 3, 62, 3). <span class=\"greek\">περὶ</span> <span class=\"greek\">μετανοίας</span> <span class=\"greek\">λαλεῖν</span> 1 Cl 8:1. <span class=\"greek\">ἀκούσαντες</span> <span class=\"greek\">ταύτην</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">μετάνοιαν</span>, quando ouviram falar desse arrependimento Hs 8, 10, 3; <span class=\"greek\">παιδεύεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>., ser disciplinado a fim de arrepender-se 1 Cl 57:1. <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">ἄγειν</span> <span class=\"greek\">τινά</span> (EpArist 188; Jos., Ant. 4, 144; cf. Appian, Bell. Civ. 2, 63 §262 <span class=\"greek\">θεοῦ</span> <span class=\"greek\">σφᾶς</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">μετάνοιαν</span> <span class=\"greek\">ἄγοντος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:4</a>; <span class=\"greek\">ἀνακαινίζειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:6</a>; <span class=\"greek\">χωρῆσαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>., chegar ao arrependimento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:9</a>. <span class=\"greek\">μετάνοιαν</span> <span class=\"greek\">λαμβάνειν</span>, receber arrependimento (após negar Cristo) Hs 9, 26, 6a. <span class=\"greek\">μετανοίας</span> <span class=\"greek\">μετασχεῖν</span> 1 Cl 8:5. <span class=\"greek\">μετάνοιαν</span> <span class=\"greek\">ἔχειν</span>, ter possibilidade de arrependimento Hm 4, 3, 3; Hs 8, 8, 2. <span class=\"greek\">ἐστί</span> <span class=\"greek\">τινι</span> <span class=\"greek\">μετάνοιαν</span>, existir para alguém possibilidade de arrependimento Hv 2, 2, 5c; 3, 7, 5; Hs 8, 8, 5; 8, 9, 4a; 9, 19, 1; 9, 20, 4. <span class=\"greek\">τινὶ</span> <span class=\"greek\">μετάνοιά</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">μία</span>, ter (somente) uma oportunidade de arrependimento m 4, 1, 8; cf. 4, 3, 1. <span class=\"greek\">μ</span>. <span class=\"greek\">κεῖταί</span> <span class=\"greek\">τινι</span>, o arrependimento está pronto, disponível para alguém Hs 9, 19, 2f; 9, 22, 4; 9, 26, 6b. <span class=\"greek\">ἐπίκειταί</span> <span class=\"greek\">τινι</span> 8, 7, 2a. <span class=\"greek\">γίνεταί</span> <span class=\"greek\">τινι</span> 9, 26, 5; <span class=\"greek\">εἰς</span> <span class=\"greek\">μάτην</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">μ</span>., é em vão 6, 1, 3. <span class=\"greek\">ταχινὴ</span> <span class=\"greek\">ὀφείλει</span> <span class=\"greek\">εἶναι</span>, deve ocorrer prontamente 8, 9, 4b. <span class=\"greek\">ἡ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">σύνεσίς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">μεγάλη</span>, o arrependimento é grande entendimento m 4, 2, 2. <span class=\"greek\">μ</span>. <span class=\"greek\">καθαρά</span> 12, 3, 2; cf. Hs 7:6. <span class=\"greek\">μ</span>. <span class=\"greek\">ἁμαρτίας</span>, arrependimento pelo pecado 2 Cl 16:4; cf. Hm 4, 3, 3. <span class=\"greek\">μ</span>. <span class=\"greek\">ζωῆς</span>, arrependimento que conduz à vida Hs 6, 2, 3; cf. 8, 6, 6. <span class=\"greek\">ἐλπὶς</span> <span class=\"greek\">μετανοίας</span>, esperança de arrependimento ou conversão IEph 10:1; Hs 6, 2, 4; 8, 7, 2b; 8, 10, 2. Com <span class=\"greek\">πίστις</span> e outras virtudes cristãs 1 Cl 62:2. O <span class=\"greek\">ἄγγελος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μ</span>., anjo do arrependimento, aparece em Hermas como proclamador do arrependimento: v 5:7; m 12, 4, 7; 12, 6, 1; Hs 9, 1, 1; 9, 14, 3; 9, 23, 5; 9, 24, 4; <span class=\"greek\">λυπεῖσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μ</span>., sentir tristeza que conduz ao arrependimento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:9</a>, <span class=\"greek\">λύπη</span> <span class=\"greek\">μετάνοιαν</span> <span class=\"greek\">ἐργάζεται</span> (cf. Plut., Mor. 476f), versículo 10.—Tendo em vista o uso cristão da palavra, Policarpo declara: <span class=\"greek\">ἀμετάθετος</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κρειττόνων</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">χείρω</span> <span class=\"greek\">μετάνοια</span>, para nós é impossível o “arrependimento” do melhor para o pior MPol 11:1.—WHolladay, The Root Šûbh in the OT, ’58.—TRE VII 446–51; RAC II 105–18.—DELG s.v. <span class=\"greek\">νόος</span>. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0233-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεταξύ</h1><div class=\"entry-meta\"><span>advérbio e preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεταξύ</span> (<span class=\"greek\">μετά</span>, <span class=\"greek\">ξύν</span> [<span class=\"greek\">σύν</span>]), advérbio (Hom.+; quanto à LXX, ver Johannessohn, Präp. 173f).</p><p class=\"entry-text\">① Indicador de intervalo que separa: entre, no meio, próximo.</p><p class=\"entry-text\">ⓐ De espaço.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Como advérbio (Hom.+): entre, no meio. <span class=\"greek\">τὸ</span> <span class=\"greek\">μεταξύ</span>, aquilo que fica no meio (Aeneas Tact. 1420; Dio Chrys. 18 [35], 1) Dg 7:2 (cf. Philo, Det. Pot. Ins. 80 <span class=\"greek\">τὰ</span> <span class=\"greek\">μ</span>.); IPhld 7:1 (Lgtft. traduz “quando eu estava entre vós”).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Empregado como preposição com genitivo (Hdt. e outros): no meio de (Polyb. 14, 1, 9; Aelian, VH 3, 1; En 14:11; 18:3; ViJer 14 [p. 73, 14 Sch.]; Jos., Ant. 3, 147 <span class=\"greek\">μ</span>. <span class=\"greek\">αὐτῆς</span> [<span class=\"greek\">τ</span>. <span class=\"greek\">λυχνίας</span>] <span class=\"greek\">καὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">τραπέζης</span>; Just., A I, 26, 2 <span class=\"greek\">μ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">δύο</span> <span class=\"greek\">γεφυρῶν</span>) <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ναοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θυσιαστηρίου</span>, entre o santuário e o altar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:35</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:51</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὑμῶν</span> 16:26. <span class=\"greek\">μ</span>. <span class=\"greek\">δύο</span> <span class=\"greek\">στρατιωτῶν</span>, entre dois soldados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:6</a>. <span class=\"greek\">μ</span>. <span class=\"greek\">θηρίων</span> <span class=\"greek\">μ</span>. <span class=\"greek\">θεοῦ</span>, (estar) entre as feras (é estar) com Deus ISm 4:2. <span class=\"greek\">μ</span>. certamente deve ser restaurado em Ox 1081, 4 (ver <span class=\"greek\">διαφορά</span>). Seguido de relativo: <span class=\"greek\">μ</span>. <span class=\"greek\">ὧν</span> <span class=\"greek\">ἐλάλουν</span>, entre as palavras do meu discurso IPhld 7:1, variante de leitura (ver Hdb. ad loc. sobre a incerteza do texto).</p><p class=\"entry-text\">ⓑ De tempo.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Entre (Pla., Rep. 5, 450c; Jos., Ant. 2, 169; Just., D. 51, 2) <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μεταξύ</span>, nesse ínterim (X., Symp. 1, 14; BGU 1139, 8 [5 a.C.]; PTebt 24, 42; 72, 190; PFlor 36, 5; TestZeb 2:7; Jos., Ant. 14, 434) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:31</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Depois, em seguida (Plut., Mor. 58b; 240a; Achilles Tat. 1, 13, 1; Mitt-Wilck. II/2, 57, 11 [40/41 d.C.]; 64, 5; Jos., Bell. 2, 211, Ant. 10, 45; Theoph. Ant. 1, 8 [p. 76, 6]; Schwyzer I 625, 2) <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μεταξὺ</span> <span class=\"greek\">σάββατον</span>, no sábado seguinte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:42</a> (Renehan ’75, 137). Cf. 23:25, variante de leitura; 1 Cl 44:2f. <span class=\"greek\">ὁ</span> <span class=\"greek\">λαὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">μεταξύ</span>, o povo que ainda há de vir 13:5.</p><p class=\"entry-text\">② Indicador de relação recíproca, uma diferença: entre (PRein 44, 16 [104 d.C.] <span class=\"greek\">τῆς</span> <span class=\"greek\">συμφωνίας</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γενομένης</span> <span class=\"greek\">μεταξὺ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">Ἰσιδώρας</span>; POxy 1117, 3 <span class=\"greek\">μ</span>. <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἀρχόντων</span>) <span class=\"greek\">μ</span>. <span class=\"greek\">σοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">μόνου</span>, entre ti e ele somente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:15</a>. Testemunhas <span class=\"greek\">μ</span>. <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡμῶν</span>, entre nós e vós 1 Cl 63:3.—<span class=\"greek\">διακρίνειν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τινος</span> <span class=\"greek\">καί</span> <span class=\"greek\">τινος</span>, fazer distinção entre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:9</a>. <span class=\"greek\">τοσαύτη</span> <span class=\"greek\">τις</span> <span class=\"greek\">διαφορὰ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">τε</span> <span class=\"greek\">ἀπίστων</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐκλεκτῶν</span> MPol 16:1. <span class=\"greek\">διαφορὰ</span> <span class=\"greek\">πολλὴ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">δύο</span> <span class=\"greek\">ὁδῶν</span>, grande diferença entre D 1:1.—<span class=\"greek\">μεταξὺ</span> <span class=\"greek\">ἀλλήλων</span> (PGen 48, 11 <span class=\"greek\">μ</span>. <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ἀλλήλων</span>), entre si, uns com os outros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:15</a>.—DELG s.v. <span class=\"greek\">μετά</span>. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0233-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεταπαραδίδωμι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεταπαραδίδωμι</span> (Vett. Val. 163, 25; Iambl., Vi. Pyth. 32, 226; inscrições, papiros; PGM 4, 501), em nossa literatura apenas intransitivo e numa única ocorrência: dar lugar a, suceder, seguir <span class=\"greek\">ἀλλήλοις</span>, uns aos outros, acerca das estações do ano 1 Cl 20:9.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0233-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεταπέμπω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεταπέμπω</span> (Hdt. e outros; inscrições, papiros, LXX, Joseph.), em nossa literatura apenas nas vozes média e passiva; 1º aoristo médio <span class=\"greek\">μετεπεμψάμην</span>, imperativo <span class=\"greek\">μετάπεμψαι</span>; 1º aoristo passivo, particípio <span class=\"greek\">μεταπεμφθείς</span>. Mandar chamar, convocar <span class=\"greek\">τινά</span>, alguém (Hippocr., Ep. 6; Appian, Iber. 10 §38; Gen 27:45; Num 23:7; EpArist 179; Jos., Vi. 69) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:5</a>, 29b; 11:13; 20:1 (<span class=\"greek\">προσκαλεσάμενος</span>, variante de leitura); 24:24, 26; GJs 21:2. Com acusativo de pessoa e indicação do lugar para onde é convocada: <span class=\"greek\">μεταπέμψασθαί</span> <span class=\"greek\">σε</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκον</span> <span class=\"greek\">αὐτοῦ</span>, convocar-te à casa dele 10:22. <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἰερουσαλήμ</span> 25:3 (Jos., C. Ap. 1, 92 <span class=\"greek\">τ</span>. <span class=\"greek\">ἀδελφοὺς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Αἴγυπτον</span>). Sem acusativo (facilmente suprido pelo contexto) e com indicação do lugar de onde procede a convocação: <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ἀνατολῆς</span> <span class=\"greek\">μεταπεμψάμενος</span>, visto que (Deus) convocou (o bispo) do Oriente IRo 2:2.—Passivo: <span class=\"greek\">μεταπεμφθείς</span>, quando fui chamado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:29a</a> (Jos., Ant. 6, 164 <span class=\"greek\">ἧκεν</span> <span class=\"greek\">μεταπεμφθείς</span>).—M-M s.v. <span class=\"greek\">μεταπέμπομαι</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0233-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεταστρέφω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεταστρέφω</span>, futuro <span class=\"greek\">μεταστρέψω</span>; 1º aoristo <span class=\"greek\">μετέστρεψα</span>. Passivo: 2º futuro <span class=\"greek\">μεταστραφήσομαι</span>; 2º aoristo <span class=\"greek\">μετεστράφην</span>; imperativo <span class=\"greek\">μεταστραφήτω</span> (Hom. e outros; PGM 4, 2625; LXX): produzir uma mudança de estado ou condição, mudar, alterar <span class=\"greek\">τὶ</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>, uma coisa em outra, muitas vezes em seu contrário (Ps 77:44; Sir 11:31 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἀγαθὰ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κακά</span>. Cf. TestAsh 1:8), o sol em trevas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:20</a> (Jo 3:4). Riso em tristeza <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:9</a>, variante de leitura (cf. Am 8:10; 1 Macc 9:41; ParJer 6:6). Com acusativo da coisa: <span class=\"greek\">μ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>, mudar ou deturpar o evangelho de Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:7</a>.—Da influência de Maria sobre os discípulos: <span class=\"greek\">μετέστρεψεν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">νοῦν</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἐ̣</span>[<span class=\"greek\">π</span>’ <span class=\"greek\">ἀγαθόν</span>], (Maria) mudou-lhes a disposição mental [para melhor] GMary Ox 3525, 13.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0233-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετασχηματίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μετασχηματίζω</span>, futuro <span class=\"greek\">μετασχηματίσω</span>; 1º aoristo <span class=\"greek\">μετεσχημάτισα</span>.</p><p class=\"entry-text\">① Mudar a forma de alguma coisa, transformar, modificar (Pla., Leg. 10 p. 903e; 906c; Aristot., De Caelo 3, 1 p. 298b, 31; Plut., Ages. 603 [14, 2], Mor. 426e; 680a; Sext. Emp., Math. 10, 335; LXX; TestSol 20:13; TestJob; TestReub 5:6; Philo, Aet. M. 79; Jos., Ant. 7, 257; Chaeremon, Fgm. 20 D p. 34 H.; Theoph. Ant. 2, 6 [p. 108, 16]) <span class=\"greek\">μ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ταπεινώσεως</span> <span class=\"greek\">ἡμῶν</span>, transformar nosso corpo humilde para assemelhá-lo ao corpo glorioso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:21</a> (cf. Philo, Leg. ad Gai. 80).—DHall, NTS, 40, ’94, 143–47, sustenta esse uso “normal” em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:6</a>, contra a interpretação da acepção 3 abaixo.</p><p class=\"entry-text\">② Fingir ser o que não se é, mudar/disfarçar-se, na voz média (Jos., Ant. 8, 267), absolutamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:15</a>. Com <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>, em algo ou como algo (Diod S 3, 57, 5 <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀθανάτους</span> <span class=\"greek\">φύσεις</span>; 4 Macc 9:22; TestJob 17:2 <span class=\"greek\">εἰς</span> <span class=\"greek\">βασιλέα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Περσῶν</span>) <span class=\"greek\">ὁ</span> <span class=\"greek\">σατανᾶς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἄγγελον</span> <span class=\"greek\">φωτός</span>, Satanás se disfarça de anjo (procedente da esfera) da luz, versículo 14 (cf. TestReub 5:6: os anjos da guarda <span class=\"greek\">μετεσχηματίζοντο</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἄνδρα</span>). Dos falsos apóstolos, <span class=\"greek\">μετασχηματιζόμενοι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀποστόλους</span> <span class=\"greek\">Χριστοῦ</span>, que se apresentam falsamente como apóstolos, versículo 13 (JColson, JTS 17, 1916, 379ff; cf. Hippol., Ref. 10, 32, 5 <span class=\"greek\">οἱ</span> <span class=\"greek\">αἱρεσιάρχοι</span> <span class=\"greek\">ὁμοίοις</span> <span class=\"greek\">λόγοις</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">ἐκείνων</span> <span class=\"greek\">προειρημένα</span> <span class=\"greek\">μετασχηματίσαντε</span>).</p><p class=\"entry-text\">③ Demonstrar uma conexão ou pertinência de uma coisa a outra, aplicar a. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:6</a> é um caso singular (para uso semelhante, ver <span class=\"greek\">σχηματίζειν</span> e <span class=\"greek\">σχῆμα</span> em Philostrat., Vi. Soph. 2, 17, 1; 2, 25, 1. Em Ps.-Demetr., Eloc. 287; 292–94, <span class=\"greek\">σχηματίζειν</span> significa “dizer alguma coisa com auxílio de uma figura de linguagem”; sobre os recursos retóricos, ver BFiore, Covert Illusion in 1 Cor 1–4: CBQ 47, ’85, 85–102; CClassen, WienerStud 107/8, ’94/95, 326f): <span class=\"greek\">ταῦτα</span> <span class=\"greek\">μετεσχημάτισα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἐμαυτὸν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">Ἀπόλλων</span>, apliquei isso a Apolo e a mim mesmo = dei a este meu ensinamento a forma de uma exposição relativa a Apolo e a mim mesmo (ver Hall, em 1 acima).—New Docs 3, 76. DELG s.v. <span class=\"greek\">ἔχω</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0233-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετατίθημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μετατίθημι</span>, forma alternativa do presente na 3ª pessoa plural <span class=\"greek\">μετατίθονται</span> AcPl Ha 2, 26 (ver B-D-F §94, 1); futuro <span class=\"greek\">μεταθήσω</span> Is 29:14; 1º aoristo <span class=\"greek\">μετέθηκα</span>; particípio do 2º aoristo <span class=\"greek\">μεταθείς</span>. Passivo: futuro na 3ª pessoa singular <span class=\"greek\">μετατεθήσεται</span> Is 29:17; 1º aoristo <span class=\"greek\">μετετέθην</span> (Hom.+), em geral “mudar (a posição de)”.</p><p class=\"entry-text\">① Levar de um lugar para outro, pôr noutro lugar, transferir <span class=\"greek\">τὴν</span> <span class=\"greek\">χεῖρα</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span>, transferir a mão para alguma coisa 13:5. Com acusativo de pessoa e indicação do destino: <span class=\"greek\">μεταθέντες</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">καροῦχαν</span>, fizeram com que ele fosse transferido para a carruagem MPol 8:2. Passivo, de cadáveres: <span class=\"greek\">μετετέθησαν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Συχέμ</span>, foram levados de volta a Siquém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:16</a>. Com indicação do lugar de onde se parte: <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">βασάνων</span>, ser retirado do (lugar de) tormento Hv 3, 7, 6 (<span class=\"greek\">μετατίθημι</span> <span class=\"greek\">ἐκ</span> em inscrição funerária de Amástris: JÖAI 28 Beibl. ’33, col. 81f n.º 39). De Enoque: ser arrebatado, trasladado, levado (ao céu) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:5a</a>; 1 Cl 9:3 (cf. Sir 44:16; Wsd 4:10); o ativo no mesmo sentido e relativo à mesma pessoa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:5b</a> (Gen 5:24).</p><p class=\"entry-text\">② Produzir mudança de estado ou condição, mudar, alterar (Hdt. 5, 68 e outros; Jos., Ant. 15, 9; IAndrosIsis, Kyme 4: os <span class=\"greek\">νόμοι</span> de Ísis não estão sujeitos à alteração por seres humanos) <span class=\"greek\">τὶ</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>, uma coisa em outra (Esth 4:17s <span class=\"greek\">μετάθες</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">καρδίαν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μῖσος</span>) <span class=\"greek\">τὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">χάριτα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀσέλγειαν</span>, perverter a graça de nosso Deus em dissolução Jd 4. Passivo, <span class=\"greek\">μετατιθεμένης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἱερωσύνης</span>, quando o sacerdócio é mudado, isto é, transmitido a outrem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:12</a> (Jos., Ant. 12, 387: da transferência do cargo de sumo sacerdote a outra pessoa).—De uma alteração gravíssima de condição: ruir, colapsar, <span class=\"greek\">μεγάλαι</span> <span class=\"greek\">πόλεις</span> <span class=\"greek\">μετατίθονται</span> AcPl Ha 2, 25f.</p><p class=\"entry-text\">③ Mudar de pensamento quanto à lealdade, mudar de opinião, afastar-se, desertar, na voz média (Polyb. 5, 111, 8; 24, 9, 6; Diod S 11, 4, 6; 2 Macc 7:24 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πατρίων</span>.—<span class=\"greek\">ὁ</span> <span class=\"greek\">μεταθέμενος</span> em Diog. L. 7, 166 e Athen. 7, 281d [neste último sem artigo] refere-se a Dionísio, o Apóstata, que abandonou os estoicos e adotou o epicurismo) <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>, de algo para algo. <span class=\"greek\">μ</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">καλέσαντος</span> <span class=\"greek\">ὑμᾶς</span> … <span class=\"greek\">εἰς</span> <span class=\"greek\">ἕτερον</span> <span class=\"greek\">εὐαγγέλιον</span>, abandonar aquele que vos chamou (e voltar-se) para outro evangelho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:6</a> (cf. Hierocles 7 p. 429: não deve haver concessão aos <span class=\"greek\">μεταβαλλομένοις</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">φιλοσοφίαν</span> <span class=\"greek\">σπουδῆς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἑτέραν</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βίου</span> <span class=\"greek\">πρόθεσιν</span>; Just., D. 47, 5 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">εὐσεβείας</span> … <span class=\"greek\">ἐπὶ</span> … <span class=\"greek\">ἀθεότητα</span>; Field, Notes 188). <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">χαλεπῶν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">δίκαια</span>, abandonar o mal em favor do bem MPol 11:1 (cf. Just., A I, 45, 6 e D. 107, 2 e outros).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0233-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετατρέπω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μετατρέπω</span>, 1º aoristo na 3ª pessoa singular <span class=\"greek\">μετέτρεψε</span>, infinitivo <span class=\"greek\">μετατρέψαι</span> (ambos na LXX). Passivo: 2º aoristo <span class=\"greek\">μετετράπην</span>, imperativo <span class=\"greek\">μετατραπήτω</span> (Hom. e outros; 4 Macc; EpArist 99; Philo), virar, mudar de direção; passivo, ser transformado (Quint. Smyrn. 11, 270), o riso em tristeza <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:9</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0233-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεταυτίκα</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεταυτίκα</span> (Hdt. 2, 161; 5, 112), advérbio, logo depois AcPl Ha 7, 8f: <span class=\"greek\">μεταυ̣</span>[<span class=\"greek\">τίκα</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">οὕτ</span>]<span class=\"greek\">ως</span>.—DELG s.v. <span class=\"greek\">αὐτός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0233-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεταφέρω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεταφέρω</span>, subjuntivo do 1º aoristo na 1ª pessoa plural <span class=\"greek\">μετενέγκωμεν</span> 1 Ch 13:3; 1º aoristo passivo <span class=\"greek\">μετηνέχθην</span> (Trag., X., Pla.+; inscrições, papiros, LXX, TestSol, EpArist), transportar para outro lugar, na voz passiva (Jos., Ant. 3, 103), acerca de pedras <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πύργου</span>, da torre Hs 9, 6, 5; 9, 8, 1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0233-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μεταφυτεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μεταφυτεύω</span>, imperativo do 1º aoristo passivo <span class=\"greek\">μεταφυτεύθητι</span> (cf. <span class=\"greek\">φυτόν</span>; Theophr., HP 2, 6, 3; 4; En; Ps 91:14 Aq., Sym., Theod.; Ps 1:3 Aq.), transplantar; na voz passiva, ser transplantado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:6</a> D.—DELG s.v. <span class=\"greek\">φύομαι</span> C.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0233-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετέβη</h1><div class=\"entry-meta\"><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μετέβη</span>, ver <span class=\"greek\">μεταβαίνω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0233-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετενδύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μετενδύω</span> (Lucian e outros), na voz média (desde Strabo, também Joseph.), mudar de roupa; particípio aoristo <span class=\"greek\">μετενδυσαμένη</span> <span class=\"greek\">σκυθρωπότερα</span> <span class=\"greek\">ἱμάτια</span> <span class=\"greek\">ἀπῆλθεν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">αὐτόν</span>, ela (Armetila) vestiu roupas mais escuras e foi até ele (Paulo) AcPl Ha 2, 16.—DELG s.v. <span class=\"greek\">δύω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0233-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετέπειτα</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μετέπειτα</span>, advérbio (Hom. e outros; OGI 177, 14; SEG XXVII, 406, 5; LXX, EpArist; Jos., Ant. 6, 66; Just.), depois, posteriormente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:17</a>; Hv 2, 4, 2.—New Docs 2, 91. DELG s.v. <span class=\"greek\">εἶτα</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0233-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετέχω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μετέχω</span>, futuro <span class=\"greek\">μεθέξω</span> (Just., Tat.); 2º aoristo <span class=\"greek\">μετέσχον</span>, infinitivo <span class=\"greek\">μετασχεῖν</span>; perfeito <span class=\"greek\">μετέσχηκα</span> (Pind., Hdt.+).</p><p class=\"entry-text\">① Ter parte ou participação em alguma coisa, compartilhar, participar, com genitivo da coisa de que se participa (B-D-F §169, 1; Rob. 509) <span class=\"greek\">πάντων</span> Dg 5:5. <span class=\"greek\">μετανοίας</span> 1 Cl 8:5. <span class=\"greek\">φυλῆς</span> <span class=\"greek\">ἑτέρας</span>, pertencer a outra tribo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:13</a> (cf. Thu. 8, 86, 3). <span class=\"greek\">τῶν</span> <span class=\"greek\">εὐεργεσιῶν</span>, participar dos benefícios Dg 8:11; <span class=\"greek\">θεοῦ</span> <span class=\"greek\">μ</span>., participar de Deus IEph 4:2 (cf. Jos., C. Ap. 1, 232 <span class=\"greek\">θείας</span> <span class=\"greek\">μ</span>. <span class=\"greek\">φύσεως</span>). <span class=\"greek\">μετέσχεν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">αὐτῶν</span>, ele compartilhou das mesmas coisas (isto é, carne e sangue) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:14</a>. Também de direitos: <span class=\"greek\">τῆς</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἐξουσίας</span> <span class=\"greek\">μ</span>., exercer autoridade sobre vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:12</a>. Absolutamente: <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἐλπίδι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μετέχειν</span> (subentendido <span class=\"greek\">τῶν</span> <span class=\"greek\">καρπῶν</span>), na esperança de aproveitar as colheitas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:10</a>, a menos que corresponda à acepção 2.—Com acusativo: a variante de leitura <span class=\"greek\">ἄνδρα</span> <span class=\"greek\">μ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:34</a> significa ter relação com um marido, isto é, ter marido.</p><p class=\"entry-text\">② Participar de alguma coisa em comum com alguém, comer, beber, desfrutar, especialmente de alimentos (Just., D. 20, 3 <span class=\"greek\">τῶν</span>…<span class=\"greek\">τροφιμωτάτων</span>…<span class=\"greek\">ἐφιέμεθα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μετέχομεν</span>): <span class=\"greek\">ὁ</span> <span class=\"greek\">μετέχων</span> <span class=\"greek\">γάλακτος</span>, aquele que se alimenta de leite <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:13</a>. <span class=\"greek\">εἰ</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">χάριτι</span> <span class=\"greek\">μετέχω</span> (subentendido <span class=\"greek\">τῆς</span> <span class=\"greek\">τροφῆς</span>), se como com gratidão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:30</a>. Também <span class=\"greek\">μ</span>. <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span>: <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἑνὸς</span> <span class=\"greek\">ἄρτου</span>, participar de, comer de um mesmo pão 10:17 (ver Thieme 29f). Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:10</a>, ver 1 acima.—Por sinédoque: <span class=\"greek\">τραπέζης</span> <span class=\"greek\">κυρίου</span>, <span class=\"greek\">δαιμονίων</span>, participar da mesa do Senhor, da mesa dos demônios, isto é, da Ceia do Senhor e de banquetes politeístas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:21</a> (Philostrat., Vi. Soph. 2, 15, 1 <span class=\"greek\">μ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱεροῦ</span>; New Docs 1, n.º 3, 9 [I/II d.C.] <span class=\"greek\">μ</span>. <span class=\"greek\">μυστηρίων</span>.—<span class=\"greek\">μ</span>. <span class=\"greek\">τραπέζης</span> como em Lucian, Cyn. 7; Philo, De Jos., 196).—M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0233-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετεωρίζομαι</h1><div class=\"entry-meta\"><span>verbo depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μετεωρίζομαι</span> (<span class=\"greek\">μετέωρος</span>, “suspenso no ar”), futuro na 3ª pessoa singular <span class=\"greek\">μετεωρισθήσεται</span> Mi 4:1; aoristo na 3ª pessoa plural <span class=\"greek\">μετεωρίσθησαν</span> LXX; em geral, “ser elevado, levantado” (Aristoph. e outros no sentido “elevar”; papiros, LXX, Philo, Joseph.). Em nossa literatura, apenas uma vez, passivo e figurado: <span class=\"greek\">μὴ</span> <span class=\"greek\">μετεωρίζεσθε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:29</a>. Nesse contexto, dificilmente pode significar outra coisa senão não fiqueis ansiosos, preocupados (o verbo tem esse sentido em Polyb. 5, 70, 10; POxy 1679, 16 <span class=\"greek\">μὴ</span> <span class=\"greek\">μετεωρίζου</span>, <span class=\"greek\">καλῶς</span> <span class=\"greek\">διάγομεν</span> = não te preocupes, estamos bem; Jos., Ant. 16, 135.—Tal como o adjetivo <span class=\"greek\">μετέωρος</span> = “oscilante entre esperança e temor, em suspense, inquieto, ansioso”: Thu. 2, 8, 1; Polyb. 3, 107, 6; BGU 417, 4; 6 [oposto a <span class=\"greek\">ἀμέριμνος</span>]; cf. o nosso “ficar no ar” acerca de alguma coisa). A tradução alternativa ser arrogante, presunçoso, embora possível por razões estritamente linguísticas (Diod S 13, 80, 1; 13, 92, 2; cf. Simplicius em Epict. p. 32, 13 <span class=\"greek\">μετεωρισμός</span> = soberba), apoiada pela LXX e preferida pela Vulg., Luther (alterada desde a revisão de 1975), Tyndale e outros, já não pode ser seriamente considerada.—AHarnack, Sprüche u. Reden Jesu 1907, 10; KKöhler, StKr 86, 1913, 456ff.—DELG s.v. 1 <span class=\"greek\">ἀείρω</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0233-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετῆρα</h1><div class=\"entry-meta\"><span>forma verbal remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μετῆρα</span>, ver <span class=\"greek\">μεταίρω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0233-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοικεσία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μετοικεσία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (=<span class=\"greek\">μετοικία</span>, de <span class=\"greek\">μετοικέω</span>, “mudar de moradia”; Leonidas de Tarento [III a.C.]: Anth. Pal. 7, 731, 6; Psellus p. 222, 5; LXX; <span class=\"greek\">ἐν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">μ</span>. <span class=\"greek\">Βαβυλῶνος</span> Theoph. Ant. 3, 25 [p. 256, 24]), transferência para outro lugar de residência, deportação; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μ</span>. <span class=\"greek\">Βαβυλῶνος</span>, no tempo do cativeiro babilônico <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:11</a>. <span class=\"greek\">μετὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">μ</span>. <span class=\"greek\">Βαβυλῶνος</span>, versículo 12; <span class=\"greek\">ἕως</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μ</span>. B., versículo 17; <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">μ</span>. B., no mesmo lugar (sobre o exílio babilônico 4 Km 24:16; 1 Ch 5:22; Ezk 12:11).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0233-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">μετοικίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">μετοικίζω</span> (<span class=\"greek\">μέτοικος</span>, “colono vindo do estrangeiro”), futuro ático <span class=\"greek\">μετοικιῶ</span> (B-D-F §74, 1; ver Mlt-H. 218); 1º aoristo <span class=\"greek\">μετῴκισα</span>, passivo na 3ª pessoa singular <span class=\"greek\">μετῳκίσθη</span> LXX (Aristoph. e outros; inscrições, LXX, EpArist, Philo, Joseph.; Tat. 20, 1): transferir para outro lugar de residência, reassentar <span class=\"greek\">τινὰ</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>, alguém para determinado lugar (OGI 264, 7 <span class=\"greek\">μετῴκισεν</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">παλαιὰν</span> <span class=\"greek\">πόλιν</span>; 1 Ch 8:6; EpArist 4; Jos., C. Ap. 1, 132) <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span> <span class=\"greek\">ταύτην</span>, transferiu-o para esta terra <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:4</a>. De deportação forçada: <span class=\"greek\">μετοικιῶ</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἐπέκεινα</span> <span class=\"greek\">Βαβυλῶνος</span>, deportar-vos-ei para além da Babilônia, versículo 43 (Am 5:27—cf. Theoph. Ant. 3, 25 [p. 256, 22]).—DELG s.v. <span class=\"greek\">οἶκος</span> II C 2. M-M.</p></section></article>"};
